tool_input.command:
set -e; GC="${TMPDIR}gatecheck"; rm -rf "$GC"; mkdir -p "$GC/dist" "$GC/test"
cat > "$GC/package.json" <<'EOF'
{ "name":"stub","private":true,"scripts":{
 "build":"true",
 "migrate":"node scripts/migrate.js",
 "test":"node scripts/faketest.js unit",
 "test:e2e":"node scripts/faketest.js e2e"} }
EOF
mkdir -p "$GC/scripts"
cat > "$GC/scripts/migrate.js" <<'EOF'
const {DatabaseSync}=require("node:sqlite");const fs=require("node:fs"),path=require("node:path");
const p=process.env.DATABASE_PATH||"data/links.db";fs.mkdirSync(path.dirname(p),{recursive:true});
const d=new DatabaseSync(p);
d.exec("create table if not exists links(slug text primary key, url text not null, hits integer not null default 0, created_at text not null)");
d.close();
EOF
cat > "$GC/scripts/faketest.js" <<'EOF'
const fs=require("node:fs");const kind=process.argv[2];
const i=process.argv.indexOf("--outputFile");const out=i>-1?process.argv[i+1]:null;
const files=kind==="unit"?["/x/src/health/health.controller.spec.ts"]:["/x/test/links.e2e-spec.ts"];
const j={success:true,numTotalTests:kind==="unit"?1:4,numPassedTests:kind==="unit"?1:4,numFailedTests:0,testResults:files.map(n=>({name:n}))};
if(out)fs.writeFileSync(out,JSON.stringify(j));
EOF
cat > "$GC/dist/main.js" <<'EOF'
const http=require("node:http");
const s=http.createServer((req,res)=>{
  if(req.url==="/health"){res.writeHead(200,{"content-type":"application/json"});return res.end(JSON.stringify({status:"ok"}));}
  res.writeHead(404,{"content-type":"application/json"});res.end(JSON.stringify({message:"Not Found",statusCode:404}));
});
s.listen(Number(process.env.PORT||3000),"127.0.0.1");
process.on("SIGTERM",()=>{s.close(()=>process.exit(0));});
EOF
echo "stub built at ~/tmp gatecheck"
